import{c as a,$ as d,Q as l,j as p,g as e,n as _,o,m as s}from"./chunks/framework.CWBTDBPu.js";const g=JSON.parse('{"title":"YuTeleport PlaceholderAPI","description":"","frontmatter":{"title":"YuTeleport PlaceholderAPI"},"headers":[],"relativePath":"plugins/items/yu-teleport/placeholders.md","filePath":"plugins/items/yu-teleport/placeholders.md"}'),n={name:"plugins/items/yu-teleport/placeholders.md"},u={class:"quick-actions"};function y(h,t,i,b,m,w){const r=d("CopyMarkdownButton"),c=d("CopyLLMButton");return l(),p("div",null,[t[0]||(t[0]=e("h1",{id:"yuteleport-placeholderapi",tabindex:"-1"},[_("YuTeleport PlaceholderAPI "),e("a",{class:"header-anchor",href:"#yuteleport-placeholderapi","aria-label":'Permalink to "YuTeleport PlaceholderAPI"'},"​")],-1)),e("div",u,[o(r,{page:""}),o(c,{page:""})]),t[1]||(t[1]=s(`<p>安装 PlaceholderAPI 且 <code>integrations.placeholderapi.enabled: true</code> 时，插件注册标识符 <code>yuteleport</code>。变量只读取快照，不主动加载区块或触发传送流程。唯一例外是 <code>%yuteleport_can_afford%</code>，它会安全读取经济余额，经济插件拒绝查询时返回空字符串。</p><h2 id="全局变量" tabindex="-1">全局变量 <a class="header-anchor" href="#全局变量" aria-label="Permalink to &quot;全局变量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>返回值</th></tr></thead><tbody><tr><td><code>%yuteleport_version%</code></td><td>插件版本。</td></tr><tr><td><code>%yuteleport_platform%</code></td><td><code>bukkit</code> 或 <code>folia</code>。</td></tr><tr><td><code>%yuteleport_default_language%</code></td><td>实际生效的默认语言。</td></tr><tr><td><code>%yuteleport_search_mode%</code></td><td>有效搜索模式：<code>folia</code>、<code>async</code> 或 <code>sync</code>。</td></tr><tr><td><code>%yuteleport_precache_enabled%</code></td><td>安全落点预缓存是否启用。</td></tr><tr><td><code>%yuteleport_countdown_channels%</code></td><td>倒计时通道摘要，例如 <code>chat+bossbar</code>。</td></tr><tr><td><code>%yuteleport_wait_seconds%</code></td><td>默认等待秒数。</td></tr><tr><td><code>%yuteleport_economy_enabled%</code></td><td>经济扣费是否启用。</td></tr><tr><td><code>%yuteleport_random_enabled%</code></td><td>随机传送模块是否启用。</td></tr><tr><td><code>%yuteleport_warp_enabled%</code></td><td>warp 模块是否启用。</td></tr><tr><td><code>%yuteleport_home_enabled%</code></td><td>home 模块是否启用。</td></tr><tr><td><code>%yuteleport_tpa_enabled%</code></td><td>tpa 模块是否启用。</td></tr><tr><td><code>%yuteleport_share_enabled%</code></td><td>坐标分享模块是否启用。</td></tr><tr><td><code>%yuteleport_back_enabled%</code></td><td>back 模块是否启用。</td></tr><tr><td><code>%yuteleport_warp_public_enabled%</code></td><td>公开 warp 是否启用。</td></tr><tr><td><code>%yuteleport_home_public_enabled%</code></td><td>公开 home 是否启用。</td></tr><tr><td><code>%yuteleport_warp_count%</code></td><td>全部已配置 warp 数量。</td></tr><tr><td><code>%yuteleport_public_warp_count%</code></td><td>全部公开 warp 数量。</td></tr><tr><td><code>%yuteleport_public_home_count%</code></td><td>当前在线玩家公开 home 数量。</td></tr><tr><td><code>%yuteleport_total_success%</code></td><td>本次启动以来成功次数。</td></tr><tr><td><code>%yuteleport_total_failed%</code></td><td>本次启动以来失败次数。</td></tr><tr><td><code>%yuteleport_total_cancelled%</code></td><td>本次启动以来取消次数。</td></tr><tr><td><code>%yuteleport_total_requests%</code></td><td>成功、失败、取消的总和。</td></tr><tr><td><code>%yuteleport_success_rate%</code></td><td>全局成功率百分比，无数据时为 <code>100</code>。</td></tr></tbody></table><h2 id="玩家状态变量" tabindex="-1">玩家状态变量 <a class="header-anchor" href="#玩家状态变量" aria-label="Permalink to &quot;玩家状态变量&quot;">​</a></h2><p>这些变量支持离线 UUID 快照，玩家离线后仍可返回冷却、状态和最近位置等数据。</p><table tabindex="0"><thead><tr><th>变量</th><th>返回值</th></tr></thead><tbody><tr><td><code>%yuteleport_cooldown%</code></td><td>剩余随机传送冷却秒数，向上取整。</td></tr><tr><td><code>%yuteleport_cooldown_ms%</code></td><td>剩余随机传送冷却毫秒数。</td></tr><tr><td><code>%yuteleport_cooldown_formatted%</code></td><td><code>1h 2m 3s</code> 格式的剩余冷却。</td></tr><tr><td><code>%yuteleport_cooldown_total%</code></td><td>当前玩家有效随机传送冷却总时长。</td></tr><tr><td><code>%yuteleport_cooldown_progress%</code></td><td>冷却恢复进度，范围 <code>0-100</code>。</td></tr><tr><td><code>%yuteleport_cooldown_bar%</code></td><td>十段文本进度条。</td></tr><tr><td><code>%yuteleport_ready%</code></td><td>无冷却且无待处理请求时为 <code>true</code>。</td></tr><tr><td><code>%yuteleport_pending%</code></td><td>正在等待、搜索或执行时为 <code>true</code>。</td></tr><tr><td><code>%yuteleport_status%</code></td><td>当前或最近的 <code>TeleportStatus</code> 小写值。</td></tr><tr><td><code>%yuteleport_type%</code></td><td>当前或最近的 <code>TeleportType</code>，例如 <code>random</code>、<code>warp</code>、<code>home</code>、<code>tpa</code>、<code>share</code>、<code>back</code>。</td></tr><tr><td><code>%yuteleport_last_type%</code></td><td>最近记录的传送类型。</td></tr><tr><td><code>%yuteleport_last_world%</code></td><td>最近目的地世界名。</td></tr><tr><td><code>%yuteleport_last_x%</code>、<code>%yuteleport_last_y%</code>、<code>%yuteleport_last_z%</code></td><td>最近目的地坐标。</td></tr><tr><td><code>%yuteleport_last_updated%</code></td><td>快照更新时间，Unix 毫秒。</td></tr><tr><td><code>%yuteleport_has_last_location%</code></td><td>是否存在最近目的地快照。</td></tr><tr><td><code>%yuteleport_player_success%</code></td><td>该玩家本次启动以来成功次数。</td></tr><tr><td><code>%yuteleport_player_failed%</code></td><td>该玩家本次启动以来失败次数。</td></tr><tr><td><code>%yuteleport_player_cancelled%</code></td><td>该玩家本次启动以来取消次数。</td></tr></tbody></table><h2 id="分类型冷却" tabindex="-1">分类型冷却 <a class="header-anchor" href="#分类型冷却" aria-label="Permalink to &quot;分类型冷却&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>返回值</th></tr></thead><tbody><tr><td><code>%yuteleport_cooldown_random%</code></td><td>随机传送冷却秒数。</td></tr><tr><td><code>%yuteleport_cooldown_warp%</code></td><td>warp 冷却秒数。</td></tr><tr><td><code>%yuteleport_cooldown_home%</code></td><td>home 冷却秒数。</td></tr><tr><td><code>%yuteleport_cooldown_tpa%</code></td><td>tpa 冷却秒数。</td></tr><tr><td><code>%yuteleport_cooldown_share%</code></td><td>坐标分享传送冷却秒数。</td></tr><tr><td><code>%yuteleport_cooldown_back%</code></td><td>back 冷却秒数。</td></tr><tr><td><code>%yuteleport_cooldown_&lt;type&gt;_ms%</code></td><td>指定类型冷却毫秒数。</td></tr><tr><td><code>%yuteleport_cooldown_&lt;type&gt;_formatted%</code></td><td>指定类型冷却格式化文本。</td></tr></tbody></table><p><code>&lt;type&gt;</code> 可写 <code>random</code>、<code>warp</code>、<code>home</code>、<code>tpa</code>、<code>share</code>、<code>back</code>。</p><h2 id="在线玩家上下文" tabindex="-1">在线玩家上下文 <a class="header-anchor" href="#在线玩家上下文" aria-label="Permalink to &quot;在线玩家上下文&quot;">​</a></h2><p>这些变量需要玩家在线；离线时返回空字符串。</p><table tabindex="0"><thead><tr><th>变量</th><th>返回值</th></tr></thead><tbody><tr><td><code>%yuteleport_group%</code></td><td>当前命中的权限组名，无匹配时为 <code>default</code>。</td></tr><tr><td><code>%yuteleport_cost%</code></td><td>当前世界随机传送有效费用。</td></tr><tr><td><code>%yuteleport_can_afford%</code></td><td>当前余额是否足够支付随机传送。</td></tr><tr><td><code>%yuteleport_wait_effective%</code></td><td>绕过权限后的有效等待秒数。</td></tr><tr><td><code>%yuteleport_bypass_cooldown%</code></td><td>是否拥有冷却绕过权限。</td></tr><tr><td><code>%yuteleport_bypass_cost%</code></td><td>是否拥有费用绕过权限。</td></tr><tr><td><code>%yuteleport_bypass_wait%</code></td><td>是否拥有等待绕过权限。</td></tr><tr><td><code>%yuteleport_world_allowed%</code></td><td>当前世界是否允许传送。</td></tr><tr><td><code>%yuteleport_world_radius_min%</code></td><td>当前世界随机传送最小半径。</td></tr><tr><td><code>%yuteleport_world_radius_max%</code></td><td>当前世界随机传送最大半径。</td></tr><tr><td><code>%yuteleport_world_max_attempts%</code></td><td>当前世界安全点最大尝试次数。</td></tr><tr><td><code>%yuteleport_precache_cached%</code></td><td>当前世界已缓存安全点数量。</td></tr><tr><td><code>%yuteleport_home_count%</code></td><td>玩家 home 数量。</td></tr><tr><td><code>%yuteleport_home_max%</code></td><td>玩家有效 home 上限。</td></tr><tr><td><code>%yuteleport_home_over_limit%</code></td><td>玩家因权限上限降低而暂时超额的 home 数量。</td></tr><tr><td><code>%yuteleport_warp_owned_count%</code></td><td>玩家自己创建的 warp 数量。</td></tr><tr><td><code>%yuteleport_warp_max%</code></td><td>玩家有效 warp 上限。</td></tr><tr><td><code>%yuteleport_visible_warp_count%</code></td><td>玩家可见 warp 数量。</td></tr><tr><td><code>%yuteleport_tpa_pending_count%</code></td><td>玩家收到的待处理 TPA 请求数量。</td></tr></tbody></table><h2 id="分类型费用与等待" tabindex="-1">分类型费用与等待 <a class="header-anchor" href="#分类型费用与等待" aria-label="Permalink to &quot;分类型费用与等待&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>返回值</th></tr></thead><tbody><tr><td><code>%yuteleport_cost_random%</code></td><td>随机传送有效费用。</td></tr><tr><td><code>%yuteleport_cost_warp%</code></td><td>warp 有效费用。</td></tr><tr><td><code>%yuteleport_cost_home%</code></td><td>home 有效费用。</td></tr><tr><td><code>%yuteleport_cost_tpa%</code></td><td>tpa 有效费用。</td></tr><tr><td><code>%yuteleport_cost_share%</code></td><td>点击坐标分享传送的有效费用。</td></tr><tr><td><code>%yuteleport_cost_back%</code></td><td>back 有效费用。</td></tr><tr><td><code>%yuteleport_can_afford_&lt;type&gt;%</code></td><td>是否能支付指定传送类型。</td></tr><tr><td><code>%yuteleport_wait_effective_&lt;type&gt;%</code></td><td>指定传送类型的有效等待秒数。</td></tr><tr><td><code>%yuteleport_cooldown_total_&lt;type&gt;%</code></td><td>指定传送类型的有效冷却总秒数。</td></tr><tr><td><code>%yuteleport_cooldown_&lt;type&gt;_total%</code></td><td>上一项的兼容别名。</td></tr></tbody></table><p>这里的 <code>&lt;type&gt;</code> 同样支持 <code>random</code>、<code>warp</code>、<code>home</code>、<code>tpa</code>、<code>share</code>、<code>back</code>。</p><h2 id="参数化变量" tabindex="-1">参数化变量 <a class="header-anchor" href="#参数化变量" aria-label="Permalink to &quot;参数化变量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>返回值</th></tr></thead><tbody><tr><td><code>%yuteleport_world_allowed_&lt;world&gt;%</code></td><td>指定世界是否允许传送，支持配置中的通配符规则。</td></tr><tr><td><code>%yuteleport_cost_&lt;world&gt;%</code></td><td>指定世界的有效随机传送费用。</td></tr></tbody></table><p><code>&lt;world&gt;</code> 保留原大小写。未知变量按 PlaceholderAPI 约定返回 <code>null</code>。</p><h2 id="本地化显示" tabindex="-1">本地化显示 <a class="header-anchor" href="#本地化显示" aria-label="Permalink to &quot;本地化显示&quot;">​</a></h2><p>在布尔变量后追加 <code>_display</code>，例如 <code>%yuteleport_ready_display%</code>，会返回语言文件中的 <code>papi-yes</code> 或 <code>papi-no</code>。<code>%yuteleport_status_display%</code> 会按查看者语言渲染状态文本。</p><h2 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/papi parse me %yuteleport_status%</span></span>
<span class="line"><span>/papi parse me %yuteleport_cooldown_formatted%</span></span>
<span class="line"><span>/papi parse me %yuteleport_platform%</span></span>
<span class="line"><span>/papi parse me %yuteleport_cost_random%</span></span>
<span class="line"><span>/papi parse me %yuteleport_back_enabled%</span></span></code></pre></div><p>修改集成开关后执行 <code>/yuteleport reload</code>，插件会注销并按新配置重新注册扩展。</p>`,23))])}const k=a(n,[["render",y]]);export{g as __pageData,k as default};
